27	func waitForLoadedSnapshot(
28	    from store: DockStore,
29	    where predicate: (DockSnapshot) -> Bool,
30	    timeout: TimeInterval = 2
31	) async -> DockSnapshot? {
32	    let deadline = Date().addingTimeInterval(timeout)
33	    while Date() < deadline {
34	        if case let .loaded(snapshot) = store.state, predicate(snapshot) {
35	            return snapshot
36	        }
37	        try? await Task.sleep(nanoseconds: 10_000_000)
38	    }
39	    return nil
40	}
