15	async function startUnixJsonRpcServer(handler, { onUpgrade = null } = {}) {
16	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "codex-dock-jsonrpc-unix-"));
17	  const socketPath = path.join(dir, "app-server.sock");
18	  const httpServer = http.createServer();
19	  const wss = new WebSocketServer({ noServer: true });
20	  const clients = new Set();
21	  httpServer.on("upgrade", (request, socket, head) => {
22	    onUpgrade?.(request);
23	    wss.handleUpgrade(request, socket, head, (ws) => {
24	      clients.add(ws);
25	      ws.on("close", () => clients.delete(ws));
26	      ws.on("message", (raw) => {
27	        const message = JSON.parse(raw.toString());
28	        const response = handler(message);
29	        if (response) {
30	          ws.send(JSON.stringify(response));
31	        }
32	      });
33	    });
34	  });
35	  await new Promise((resolve) => {
36	    httpServer.listen(socketPath, resolve);
37	  });
38	  return {
39	    socketPath,
40	    close: async () => {
41	      for (const ws of clients) {
42	        ws.close();
43	      }
44	      await new Promise((resolve, reject) => {
45	        httpServer.close((error) => {
46	          if (error) {
47	            reject(error);
48	          } else {
49	            resolve();
50	          }
51	        });
52	      });
53	      fs.rmSync(dir, { recursive: true, force: true });
54	    },
55	  };
56	}
