58	test("JsonRpcWebSocketClient adapts Codex unix:// app-server endpoints to ws+unix", async () => {
59	  let extensionHeader = null;
60	  const server = await startUnixJsonRpcServer((message) => {
61	    if (message.method === "initialize") {
62	      return { id: message.id, result: { userAgent: "unix-test" } };
63	    }
64	    if (message.method === "thread/list") {
65	      return { id: message.id, result: { data: [], nextCursor: null } };
66	    }
67	    return null;
68	  }, {
69	    onUpgrade: (request) => {
70	      extensionHeader = request.headers["sec-websocket-extensions"] || null;
71	    },
72	  });
73	  const endpoint = `unix://${server.socketPath}`;
74	  assert.equal(unixSocketPathFromURL(endpoint), server.socketPath);
75	  assert.equal(webSocketURLForEndpoint(endpoint), `ws+unix:${server.socketPath}:/`);
76	
77	  const client = new JsonRpcWebSocketClient(endpoint, { timeoutMs: 1_000 });
78	  try {
79	    await client.connect();
80	    const initialize = await client.request("initialize", {});
81	    assert.equal(initialize.userAgent, "unix-test");
82	    const list = await client.request("thread/list", {});
83	    assert.deepEqual(list, { data: [], nextCursor: null });
84	    assert.equal(extensionHeader, null);
85	  } finally {
86	    await client.close();
87	    await server.close();
88	  }
89	});
