70	async function startLoopbackAppServer({
71	  loadedThreadIDs = [],
72	  rows = {},
73	} = {}) {
74	  const wss = new WebSocketServer({ host: "127.0.0.1", port: 0 });
75	  const clients = new Set();
76	  await onceListening(wss);
77	  const url = `ws://127.0.0.1:${wss.address().port}`;
78	  wss.on("connection", (ws) => {
79	    clients.add(ws);
80	    ws.on("close", () => clients.delete(ws));
81	    ws.on("message", (raw) => {
82	      const message = JSON.parse(raw.toString());
83	      if (message.method === "initialize") {
84	        ws.send(jsonRpcResponse(message.id, {
85	          userAgent: "registry-live-test",
86	          codexHome: "/tmp/codex-dock-registry-test",
87	        }));
88	      } else if (message.method === "initialized") {
89	        return;
90	      } else if (message.method === "thread/loaded/list") {
91	        ws.send(jsonRpcResponse(message.id, { data: loadedThreadIDs }));
92	      } else if (message.method === "thread/read") {
93	        ws.send(jsonRpcResponse(message.id, {
94	          thread: rows[message.params?.threadId],
95	        }));
96	      } else if (message.method === "thread/list") {
97	        ws.send(jsonRpcResponse(message.id, { data: [], nextCursor: null }));
98	      }
99	    });
100	  });
101	  return {
102	    url,
103	    close: async () => {
104	      for (const ws of clients) {
105	        ws.close();
106	      }
107	      await closeWebSocketServer(wss);
108	    },
109	  };
110	}
