28	async function startCanonicalActivityAppServer({
29	  emitRenameNotifications = false,
30	  failTurnsFor = new Set(),
31	  loadedThreadIDs = [],
32	  listUpdatedAt = {},
33	  readUpdatedAt = {},
34	} = {}) {
35	  const wss = new WebSocketServer({ host: "127.0.0.1", port: 0 });
36	  const clients = new Set();
37	  const initializedClients = new Set();
38	  const resumedClients = new Set();
39	  await onceListening(wss);
40	  const address = wss.address();
41	  const url = `ws://127.0.0.1:${address.port}`;
42	  const rows = {
43	    older: {
44	      id: "older",
45	      sessionId: "older-session",
46	      preview: "Older list row",
47	      createdAt: 1_000,
48	      updatedAt: listUpdatedAt.older ?? 1_000,
49	      source: "cli",
50	      status: { type: "idle" },
51	      cwd: "/tmp/codex-client",
52	      gitInfo: { branch: "main" },
53	    },
54	    newer: {
55	      id: "newer",
56	      sessionId: "newer-session",
57	      preview: "Newer turn row",
58	      createdAt: 900,
59	      updatedAt: listUpdatedAt.newer ?? 900,
60	      source: "cli",
61	      status: { type: "idle" },
62	      cwd: "/tmp/codex-client",
63	      gitInfo: { branch: "main" },
64	    },
65	    "live-only": {
66	      id: "live-only",
67	      sessionId: "live-only-session",
68	      preview: "Live-only row",
69	      createdAt: 700,
70	      updatedAt: listUpdatedAt["live-only"] ?? 700,
71	      source: "cli",
72	      status: { type: "running" },
73	      cwd: "/tmp/codex-client",
74	      gitInfo: { branch: "main" },
75	    },
76	  };
77	  const renameRequests = [];
78	  const renameThreadLocally = (threadId, name) => {
79	    const thread = rows[threadId];
80	    if (!thread) {
81	      throw new Error(`missing fake thread: ${threadId}`);
82	    }
83	    thread.name = name;
84	    thread.updatedAt = Math.max(Number(thread.updatedAt || 0), 4_000);
85	  };
86	  const emitThreadNameUpdated = (threadId, threadName, { resumedOnly = false } = {}) => {
87	    const targets = resumedOnly ? resumedClients : initializedClients;
88	    let sent = 0;
89	    for (const ws of targets) {
90	      if (ws.readyState !== 1) {
91	        continue;
92	      }
93	      ws.send(appServerNotification("thread/name/updated", { threadId, threadName }));
94	      sent += 1;
95	    }
96	    return sent;
97	  };
98	  const setThreadStatusLocally = (threadId, status) => {
99	    const thread = rows[threadId];
100	    if (!thread) {
101	      throw new Error(`missing fake thread: ${threadId}`);
102	    }
103	    thread.status = status;
104	    thread.updatedAt = Math.max(Number(thread.updatedAt || 0), 4_100);
105	  };
106	  const emitThreadStatusChanged = (threadId, status, { resumedOnly = false } = {}) => {
107	    const targets = resumedOnly ? resumedClients : initializedClients;
108	    let sent = 0;
109	    for (const ws of targets) {
110	      if (ws.readyState !== 1) {
111	        continue;
112	      }
113	      ws.send(appServerNotification("thread/status/changed", { threadId, status }));
114	      sent += 1;
115	    }
116	    return sent;
117	  };
118	  wss.on("connection", (ws) => {
119	    clients.add(ws);
120	    ws.on("close", () => {
121	      clients.delete(ws);
122	      initializedClients.delete(ws);
123	      resumedClients.delete(ws);
124	    });
125	    ws.on("message", (raw) => {
126	      const message = JSON.parse(raw.toString());
127	      if (message.method === "initialize") {
128	        ws.send(appServerResponse(message.id, {
129	          userAgent: "test-app-server",
130	          codexHome: "/tmp/codex-client-test",
131	          platformFamily: "unix",
132	          platformOs: "macos",
133	        }));
134	      } else if (message.method === "initialized") {
135	        initializedClients.add(ws);
136	      } else if (message.method === "thread/list") {
137	        ws.send(appServerResponse(message.id, {
138	          data: [rows.older, rows.newer],
139	          nextCursor: null,
140	        }));
141	      } else if (message.method === "thread/loaded/list") {
142	        ws.send(appServerResponse(message.id, { data: loadedThreadIDs }));
143	      } else if (message.method === "thread/read") {
144	        const thread = { ...rows[message.params?.threadId] };
145	        if (readUpdatedAt[message.params?.threadId] !== undefined) {
146	          thread.updatedAt = readUpdatedAt[message.params.threadId];
147	        }
148	        ws.send(appServerResponse(message.id, { thread }));
149	      } else if (message.method === "thread/turns/list") {
150	        if (failTurnsFor.has(message.params?.threadId)) {
151	          ws.send(JSON.stringify({
152	            id: message.id,
153	            error: { code: -32000, message: "turn proof unavailable" },
154	          }));
155	          return;
156	        }
157	        const startedAt = {
158	          newer: 3_000,
159	          older: 2_000,
160	          "live-only": 5_000,
161	        }[message.params?.threadId] ?? 1_000;
162	        ws.send(appServerResponse(message.id, {
163	          data: [{ id: `${message.params?.threadId}-turn`, startedAt }],
164	          nextCursor: null,
165	        }));
166	      } else if (message.method === "thread/resume") {
167	        const thread = rows[message.params?.threadId];
168	        if (!thread) {
169	          ws.send(JSON.stringify({
170	            id: message.id,
171	            error: { code: -32602, message: "thread not found" },
172	          }));
173	          return;
174	        }
175	        resumedClients.add(ws);
176	        ws.send(appServerResponse(message.id, { thread }));
177	      } else if (message.method === "thread/name/set") {
178	        const thread = rows[message.params?.threadId];
179	        if (!thread) {
180	          ws.send(JSON.stringify({
181	            id: message.id,
182	            error: { code: -32602, message: "thread not found" },
183	          }));
184	          return;
185	        }
186	        renameRequests.push({
187	          threadId: message.params.threadId,
188	          name: message.params.name,
189	        });
190	        renameThreadLocally(message.params.threadId, message.params.name);
191	        ws.send(appServerResponse(message.id, {}));
192	        if (emitRenameNotifications) {
193	          setTimeout(() => {
194	            emitThreadNameUpdated(message.params.threadId, message.params.name);
195	          }, 0);
196	        }
197	      }
198	    });
199	  });
200	  return {
201	    url,
202	    renameRequests,
203	    emitThreadNameUpdated,
204	    emitThreadStatusChanged,
205	    renameThreadLocally,
206	    setThreadStatusLocally,
207	    get initializedClientCount() {
208	      return initializedClients.size;
209	    },
210	    get resumedClientCount() {
211	      return resumedClients.size;
212	    },
213	    close: async () => {
214	      for (const ws of clients) {
215	        ws.close();
216	      }
217	      await closeWebSocketServer(wss);
218	    },
219	  };
220	}
