520	    const reportDirs = passingReports.map((report) => report.dir).filter(Boolean);
521	    const duplicateReportDirs = reportDirs.filter((dir, index) => reportDirs.indexOf(dir) !== index);
522	    const status = passingReports.length >= minPasses ? "pass" : reports.length ? "fail" : "missing";
