588	      requiredScenarioCount: requiredScenarios.length,
589	      passingScenarioCount: scenarioSummaries.filter((scenario) => scenario.status === "pass").length,
590	      missingScenarioCount: scenarioSummaries.filter((scenario) => scenario.status === "missing").length,
591	      failedScenarioCount: scenarioSummaries.filter((scenario) => scenario.status === "fail").length,
592	      unexpectedScenarioCount: unexpectedScenarios.length,
593	      maxObservedUiLagMs: allLagValues.length ? Math.max(...allLagValues) : null,
594	      findings: findings.length,
595	    },
596	    scenarios: scenarioSummaries,
597	    unexpectedScenarios,
598	    findings,
599	  };
