618	  lines.push("");
619	  lines.push("## Scenarios");
620	  lines.push("");
621	  for (const scenario of report.scenarios) {
622	    lines.push(`- \`${scenario.scenario}\`: ${scenario.status}, passes ${scenario.passingReportCount}/${report.config.minPasses}, reports ${scenario.reportCount}, max UI lag ${scenario.maxObservedUiLagMs ?? "not scored"} ms`);
623	  }
624	  lines.push("");
625	  lines.push("## Findings");
626	  lines.push("");
627	  if (!report.findings.length) {
628	    lines.push("- None.");
629	  } else {
630	    for (const finding of report.findings.slice(0, 80)) {
631	      lines.push(`- \`${finding.code}\`: ${finding.message}`);
